import {
  Autocomplete,
  Box,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useState } from 'react';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import PersonIcon from '@mui/icons-material/Person';
import { useSelector } from 'react-redux';
import { selectSupplier } from '../../store/BasketSelector';
import { addSupplierDetails } from '../../store/BasketSlice';
import { useAppDispatch } from '../../../../store/hooks';
import { useGetSupplierByMobileQuery } from '../../../posApi';
import { ISupplierApiWrapper } from '../../../../core/Interface/purchaseJewellery.interface';
import AddSupplierDetails from '../AddSupplierDetails';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

const JewelSupplierSearch = () => {
  const dispatch = useAppDispatch();
  const supplier = useSelector(selectSupplier);
  const [supplierInput, setSupplierInput] = useState('');
  const [mobileOptions, setMobileOptions] = useState<string[]>([]);
  const [openSupplierDialog, setOpenSupplierDialog] = useState(false);

  const { data: supplierData, isFetching } = useGetSupplierByMobileQuery(
    supplierInput,
    { skip: supplierInput.length < 2 },
  ) as { data?: ISupplierApiWrapper; isFetching: boolean };

  useEffect(() => {
    if (supplierData?.data?.suppliers) {
      setMobileOptions(supplierData.data.suppliers.map((s) => s.mobile));
    }
  }, [supplierData]);

  useEffect(() => {
    if (supplier.mobile) setSupplierInput(supplier.mobile);
  }, [supplier.mobile]);

  const autoFill = (mobile: string) => {
    const found = supplierData?.data?.suppliers.find((s) => s.mobile === mobile);
    if (!found) return;
    dispatch(addSupplierDetails({
      supplierName: found.supplierName ?? '',
      mobile: found.mobile,
      nic: found.nic ?? '',
      address: found.address ?? '',
    }));
  };

  return (
    <Box>
      <Grid container spacing={1} sx={{ pb: 1 }}>
        {/* Mobile search */}
        <Grid item md={6}>
          <Autocomplete
            freeSolo
            loading={isFetching}
            onChange={(_, val) => {
              if (typeof val === 'string') {
                setSupplierInput(val);
                autoFill(val);
              }
            }}
            onInputChange={(_, val) => {
              setSupplierInput(val);
              autoFill(val);
            }}
            options={mobileOptions}
            value={supplierInput || ''}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <LocalShippingOutlinedIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                }}
                autoComplete="off"
                fullWidth
                placeholder="Supplier mobile…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
              />
            )}
            sx={{ width: '100%' }}
          />
        </Grid>

        {/* Supplier Name (click to open full supplier dialog) */}
        <Grid item md={6}>
          <TextField
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <PersonIcon sx={{ color: TEAL, fontSize: 17 }} />
                </InputAdornment>
              ),
              readOnly: true,
            }}
            fullWidth
            onClick={() => setOpenSupplierDialog(true)}
            placeholder="Supplier name…"
            size="small"
            sx={{
              cursor: 'pointer',
              '& .MuiOutlinedInput-input': { fontSize: 13, cursor: 'pointer' },
              '& .MuiOutlinedInput-root': {
                backgroundColor: '#fff',
                borderRadius: '10px',
                cursor: 'pointer',
                '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
              },
            }}
            value={supplier.supplierName || ''}
            variant="outlined"
          />
        </Grid>
      </Grid>

      {/* Supplier info strip */}
      {(supplier.mobile || supplier.supplierName) && (
        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', px: 0.5, pb: 0.5 }}>
          {supplier.supplierName && (
            <Typography sx={{ fontSize: 11, fontWeight: 600, color: TEAL }}>
              {supplier.supplierName}
            </Typography>
          )}
          {supplier.mobile && (
            <Typography sx={{ fontSize: 11, fontWeight: 600, color: alpha(NAVY, 0.6) }}>
              {supplier.mobile}
            </Typography>
          )}
          {supplier.nic && (
            <Typography sx={{ fontSize: 11, color: alpha(NAVY, 0.5) }}>
              NIC: {supplier.nic}
            </Typography>
          )}
        </Box>
      )}

      {openSupplierDialog && (
        <AddSupplierDetails
          handleCloseDialog={() => setOpenSupplierDialog(false)}
          openModel={openSupplierDialog}
          title="Supplier Details"
        />
      )}
    </Box>
  );
};

export default React.memo(JewelSupplierSearch);
