import * as React from 'react';
import {
  Autocomplete,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import { useFormik } from 'formik';
import { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import { selectSupplier } from '../store/BasketSelector';
import { addSupplierDetails } from '../store/BasketSlice';
import { useAppDispatch } from '../../../store/hooks';
import { useGetSupplierByMobileQuery } from '../../posApi';
import { ISupplierApiWrapper } from '../../../core/Interface/purchaseJewellery.interface';
import { useNotifier } from '../../../core/Notifier';

interface IMobile {
  openModel: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
}

const AddSupplierDetails: React.FC<IMobile> = ({
  title,
  openModel,
  handleCloseDialog,
}) => {
  const { t } = useTranslation(['purchase']);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();
  const { showErrorMessage } = useNotifier();

  const selectAddSupplier = useSelector(selectSupplier);
  const [supplierNumber, setSupplierNumber] = useState('');
  const [mobileOptions, setMobileOptions] = useState<string[]>([]);

  const { data: supplierData, isFetching } = useGetSupplierByMobileQuery(
    supplierNumber,
    {
      skip: supplierNumber.length < 2,
    }
  ) as { data?: ISupplierApiWrapper; isFetching: boolean };

  useEffect(() => {
    if (supplierData?.data?.suppliers) {
      setMobileOptions(supplierData.data.suppliers.map((s) => s.mobile));
    }
  }, [supplierData]);

  const validateMobileNumber = (value: string) =>
    value.startsWith('0')
      ? /^[0-9]{10}$/.test(value)
      : /^[1-9]{9}$/.test(value);

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      mobile: selectAddSupplier.mobile || '',
      supplierName: selectAddSupplier.supplierName || '',
      nic: selectAddSupplier.nic || '',
      address: selectAddSupplier.address || '',
    },
    onSubmit: (values) => {
      if (!validateMobileNumber(values.mobile)) {
        showErrorMessage('Mobile number should be valid');
        return;
      }
      dispatch(
        addSupplierDetails({
          supplierName: values.supplierName,
          mobile: values.mobile,
          nic: values.nic,
          address: values.address,
        })
      );
      handleClose();
    },
  });

  const autoFillSupplier = (mobile: string) => {
    const supplier = supplierData?.data?.suppliers.find(
      (s) => s.mobile === mobile
    );

    if (!supplier) return;

    formik.setFieldValue('supplierName', supplier.supplierName ?? '');
    formik.setFieldValue('nic', supplier.nic ?? '');
    formik.setFieldValue('address', supplier.address ?? '');
  };

  const formValid = useMemo(() => {
    return (
      validateMobileNumber(formik.values.mobile) &&
      formik.values.supplierName.trim().length > 0
    );
  }, [formik.values.mobile, formik.values.supplierName]);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  return (
    <form onSubmit={formik.handleSubmit}>
      <Dialog
        fullScreen={isMobile}
        maxWidth="lg"
        onClose={handleClose}
        open={openModel}
        PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
      >
        <DialogTitle sx={{ p: 0 }}>
          <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
            <Stack alignItems="center" direction="row" spacing={1.5}>
              <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                <LocalShippingOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Select supplier</Typography>
              </Box>
            </Stack>
          </Box>
        </DialogTitle>

        <DialogContent
          sx={{ width: isMobile ? 'auto' : '40vw', px: 3, pt: 3, pb: 1 }}
        >
          <Grid
            container
            spacing={2}
          >
            <Grid
              item
              sx={{ pt: 2 }}
              xs={12}
            >
              <FieldHeader title={t('purchase:mobileNumber')} />

              <Autocomplete
                freeSolo
                loading={isFetching}
                onChange={(_, value) => {
                  if (typeof value === 'string') {
                    formik.setFieldValue('mobile', value);
                    autoFillSupplier(value);
                  }
                }}
                onInputChange={(_, value) => {
                  setSupplierNumber(value);
                  formik.setFieldValue('mobile', value);
                  autoFillSupplier(value);
                }}
                options={mobileOptions}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    placeholder="Mobile Number"
                  />
                )}
                value={formik.values.mobile}
              />
            </Grid>

            <Grid
              item
              sx={{ pt: 2 }}
              xs={12}
            >
              <FieldHeader title={t('purchase:name')} />
              <TextField
                fullWidth
                name="supplierName"
                onChange={formik.handleChange}
                placeholder="Name"
                value={formik.values.supplierName}
              />
            </Grid>
            <Grid
              item
              sx={{ pt: 2 }}
              xs={12}
            >
              <FieldHeader title={t('purchase:nic')} />
              <TextField
                fullWidth
                name="nic"
                onChange={formik.handleChange}
                placeholder="NIC"
                value={formik.values.nic}
              />
            </Grid>

            <Grid
              item
              xs={12}
            >
              <FieldHeader title={t('purchase:address')} />
              <TextField
                fullWidth
                multiline
                name="address"
                onChange={formik.handleChange}
                placeholder="Address"
                rows={2}
                value={formik.values.address}
              />
            </Grid>
          </Grid>
        </DialogContent>

        <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
          <Button
            onClick={handleClose}
            sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
            variant="outlined"
          >
            {t('purchase:cancel')}
          </Button>
          <Button
            autoFocus
            disabled={!formValid}
            onClick={() => {
              formik.handleSubmit();
            }}
            sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
            type="submit"
            variant="contained"
          >
            {t('purchase:add')}
          </Button>
        </DialogActions>
      </Dialog>
    </form>
  );
};

export default React.memo(AddSupplierDetails);
