/* eslint-disable react/display-name */
import React, { useMemo } from 'react';
import {
  Box,
  CardMedia,
  Divider,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { IPurchaseReceipt } from '../../../core/Interface/purchase.interface';
import { formatDateTime } from '../../../core/utils';

export const Receipt = React.forwardRef<
  HTMLDivElement,
  {
    purchaseRes: IPurchaseReceipt;
    width: number;
    fontSize: number;
    label: string;
    fontWeight?: string;
  }
>(({ purchaseRes, width, fontSize, label, fontWeight }, ref) => {
  const PurchaseDataMemo = useMemo(() => purchaseRes, [purchaseRes]);

  const getPriceFormat = (amount: number): string => {
    return amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  };

  return (
    <Box
      ref={ref}
      sx={{
        maxWidth: width,
        pr: '20px',
        pb: '250px',
        pl: '20px',
        overflow: 'scroll',
        breakAfter: 'always',
        breakBefore: 'always',
        breakInside: 'avoid',
      }}
    >
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justify: 'center',
        }}
      >
        <CardMedia
          alt="logo"
          component="img"
          image={PurchaseDataMemo.logo}
          sx={{ height: '80px', width: '80px', mx: 'auto' }}
        />
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.headerText1}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.headerText2}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.headerText3}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.email}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.mobile}
        </Typography>
        <Divider
          flexItem
          orientation="horizontal"
        />
      </Box>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'left',
        }}
      >
        <Box sx={{ height: '7px' }} />

        {(label === '58mm' || label === '80mm') && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'row',
              gap: '4px',
              textAlign: 'left',
            }}
          >
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'left',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Receipt No
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Purchased By
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Supplier
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Date
              </Typography>
            </div>
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-end',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
            </div>

            <div
              style={{
                flex: '1',
                display: 'flex',
                flexDirection: 'column',
                gap: '0px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PurchaseDataMemo.receiptNo}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PurchaseDataMemo.purchaseBy}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PurchaseDataMemo.supplierNameOrMobile}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {formatDateTime(new Date(PurchaseDataMemo.dateTime))}
              </Typography>
            </div>
          </div>
        )}

        {(label === 'A5' || label === 'A4') && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'row',
              gap: '4px',
              textAlign: 'left',
            }}
          >
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-start',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Receipt No
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Purchased By
              </Typography>
            </div>

            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-end',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
            </div>

            <div
              style={{
                flex: '1',
                display: 'flex',
                flexDirection: 'column',
                gap: '0px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PurchaseDataMemo.receiptNo}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PurchaseDataMemo.purchaseBy}
              </Typography>
            </div>

            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',

                alignItems: 'flex-end',
              }}
            >
              {' '}
              <div
                style={{
                  flex: '0 0 auto',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-start',
                  marginRight: '4px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  Supplier
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  Date
                </Typography>
              </div>
              <div
                style={{
                  flex: '0 0 auto',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-end',
                  marginLeft: '4px',
                  marginRight: '6px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  :
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  :
                </Typography>
              </div>
              <div
                style={{
                  flex: '1',
                  display: 'flex',
                  alignItems: 'flex-start',
                  flexDirection: 'column',
                  gap: '0px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  {PurchaseDataMemo.supplierNameOrMobile}
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  {formatDateTime(new Date(PurchaseDataMemo.dateTime))}
                </Typography>
              </div>
            </div>
          </div>
        )}

        <Divider
          flexItem
          orientation="horizontal"
        />
      </Box>

      {(label === '58mm' || label === '80mm') && (
        <TableContainer sx={{ maxWidth: width }}>
          <Table sx={{ width: '100%' }}>
            <TableHead sx={{ width: '100%' }}>
              <TableRow>
                <TableCell
                  align="left"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    pl: 0,
                    color: 'black',
                  }}
                >
                  Item
                </TableCell>
                <TableCell
                  align="center"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    pl: 0,
                    color: 'black',
                  }}
                >
                  Gold Weight(g)
                </TableCell>

                <TableCell
                  align="right"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    pr: 0,
                    color: 'black',
                  }}
                >
                  Amount
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {PurchaseDataMemo &&
                PurchaseDataMemo.items &&
                PurchaseDataMemo.items.map((item, index) => (
                  <React.Fragment key={index}>
                    <TableRow sx={{ p: 0, m: 0 }}>
                      <TableCell
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          textAlign: 'left',
                          color: 'black',
                          width: '100%',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {item.productName}
                      </TableCell>
                    </TableRow>
                    <TableRow sx={{ p: 0 }}>
                      <TableCell
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {(item.goldWeight ?? 0) / 8} ×{' '}
                        {getPriceFormat(item.unitPrice)}
                      </TableCell>
                      <TableCell
                        align="center"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {item.goldWeight}
                      </TableCell>

                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {getPriceFormat(item.totalAmount)}
                      </TableCell>
                    </TableRow>
                  </React.Fragment>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {(label === 'A4' || label === 'A5') && (
        <TableContainer sx={{ maxWidth: width }}>
          <Table sx={{ width: '100%' }}>
            <TableHead sx={{ width: '100%' }}>
              <TableRow>
                <TableCell
                  align="left"
                  sx={{ fontSize: fontSize, fontWeight: 800, pl: 0 }}
                >
                  Item
                </TableCell>
                <TableCell
                  align="left"
                  sx={{ fontSize: fontSize, fontWeight: 800 }}
                >
                  Gold Weight
                </TableCell>
                <TableCell
                  align="right"
                  sx={{ fontSize: fontSize, fontWeight: 800, pr: '30px' }}
                >
                  Unit Price
                </TableCell>

                <TableCell
                  align="right"
                  sx={{ fontSize: fontSize, fontWeight: 800, pr: 0 }}
                >
                  Amount
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody sx={{ width: '100%' }}>
              {PurchaseDataMemo &&
                PurchaseDataMemo.items &&
                PurchaseDataMemo.items.map((item, index) => (
                  <React.Fragment key={index}>
                    <TableRow sx={{}}>
                      <TableCell
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          textAlign: 'left',
                          pl: 0,
                        }}
                      >
                        {item.productName}
                      </TableCell>

                      <TableCell
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                        }}
                      >
                        {item.goldWeight}
                      </TableCell>
                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          pr: '30px',
                        }}
                      >
                        {getPriceFormat(item.unitPrice)}
                      </TableCell>

                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          pr: 0,
                        }}
                      >
                        {getPriceFormat(item.totalAmount)}
                      </TableCell>
                    </TableRow>
                  </React.Fragment>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Divider
        flexItem
        orientation="horizontal"
      />
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              Sub Total{' '}
            </Typography>
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mb: '10px', textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PurchaseDataMemo.subTotal)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      <Divider
        flexItem
        orientation="horizontal"
        sx={{ border: '1px dashed #E0E0E0' }}
      />
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          mt={1}
          xs={6}
        >
          <Box>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              Total
            </Typography>
          </Box>
        </Grid>
        <Grid
          item
          mt={1}
          xs={6}
        >
          <Box sx={{ textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PurchaseDataMemo.netTotal)}
            </Typography>
          </Box>
        </Grid>
      </Grid>

      <Divider
        flexItem
        orientation="horizontal"
        sx={{ border: '1px dashed #E0E0E0' }}
      />
      <Box sx={{ height: '10px' }} />
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.footerText1}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.footerText2}
        </Typography>

        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PurchaseDataMemo.footerText3}
        </Typography>
      </Box>
    </Box>
  );
});
