import { Box } from '@mui/material';
import React from 'react';
import JewelCategory from './Category';
import JewelFourthSection from './FourthSection';
import JewelFifthSection from './FifthSection';
import JewelLastSection from './LastSection';

const PurchaseJewelleryRight = () => {
  return (
    <Box
      sx={{
        '--tile-h': 'calc((100vh - 124px) / 7)',
        position: 'fixed',
        left: 'calc(33.333% + 4px)',
        right: '4px',
        height: 'calc(100vh - 96px)',
        overflow: 'hidden',
        zIndex: 5,
        display: 'flex',
        flexDirection: 'column',
        gap: '3px',
        pt: '2px',
        pb: '8px',
      }}
    >
      <Box sx={{ flex: '0 0 auto' }}>
        <JewelCategory />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <JewelFourthSection />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <JewelFifthSection />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <JewelLastSection />
      </Box>
    </Box>
  );
};

export default React.memo(PurchaseJewelleryRight);
