/* eslint-disable react/jsx-sort-props */
import * as React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Box,
  Grid,
  Stack,
  TextField,
  Divider,
  Typography,
  useMediaQuery,
} from '@mui/material';
import DiamondOutlinedIcon from '@mui/icons-material/DiamondOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '../../../store/hooks';
import { IProductData } from '../../../core/Interface/product.interface';
import { IAddQty } from '../../../core/Interface/property.interface';
import { addItem } from '../store/BasketSlice';
import { HEADER_GRADIENT } from '../../../theme/appColors';

interface IAddPurchase {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  item?: IAddQty;
  data?: IProductData;
}

const toNum = (v: string) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

const AddPurchase: React.FC<IAddPurchase> = ({
  title,
  openModel = false,
  handleCloseDialog,
  item,
  data,
}) => {
  const { t } = useTranslation(['purchase']);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();

  const [goldPrice8g, setGoldPrice8g] = React.useState<number>(
    data?.unitPrice ?? 0
  );
  const [karatText, setKaratText] = React.useState<string>(
    item?.goldKarat ?? '22K'
  );
  const [weightG, setWeightG] = React.useState<string>(
    item?.goldWeight?.toString() ?? ''
  );
  const [wastage] = React.useState<string>(
    item?.wastage?.toString() ?? ''
  );

  const perGram = React.useMemo(
    () => (goldPrice8g > 0 ? goldPrice8g / 8 : 0),
    [goldPrice8g]
  );

  const weightValue = React.useMemo(() => toNum(weightG), [weightG]);
  const wastageValue = React.useMemo(() => toNum(wastage), [wastage]);

  const goldPriceForWeight = React.useMemo(
    () => perGram * weightValue,
    [perGram, weightValue]
  );

  const wastageAmount = React.useMemo(
    () => perGram * wastageValue,
    [perGram, wastageValue]
  );

  const finalAmount = React.useMemo(() => {
    if (perGram <= 0 || weightValue <= 0) return null;
    return goldPriceForWeight + wastageAmount;
  }, [perGram, weightValue, goldPriceForWeight, wastageAmount]);

  const handleClose = () => handleCloseDialog(false);

  const handleAdd = () => {
    if (finalAmount === null) return;

    dispatch(
      addItem({
        id: data?.id ?? '',
        name: data?.name ?? '',
        unitPrice: goldPrice8g,
        goldKarat: karatText,
        goldWeight: weightValue,
        wastage: wastageValue,
        cost: finalAmount,
        total: finalAmount,
        quanity: 1,
        freeQty: 0,
        totalQty: 1,
        sellingPrice: 0,
        price: 0,
        discount: 0,
        isDiscountPercentage: false,
        discountAmount: 0,
        totalDiscountAmount: 0,
      })
    );

    handleClose();
  };

  // eslint-disable-next-line react/no-multi-comp
  const Row = ({
    label,
    value,
    strong,
  }: {
    label: string;
    value: number | null;
    strong?: boolean;
  }) => (
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'space-between',
        py: 0.75,
      }}
    >
      <Typography fontWeight={strong ? 700 : 500}>{label}</Typography>
      <Typography fontWeight={strong ? 700 : 600}>
        {value !== null ? value.toFixed(2) : '--'}
      </Typography>
    </Box>
  );

  return (
    <Dialog
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      open={openModel}
      onClose={handleClose}
      PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
              <DiamondOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Add jewellery to purchase</Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
        <Grid
          container
          spacing={2}
        >
          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Gold Price (8g)" />
            <TextField
              fullWidth
              size="small"
              type="number"
              value={goldPrice8g}
              onChange={(e) => setGoldPrice8g(+e.target.value)}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Karat (purity)" />
            <TextField
              fullWidth
              size="small"
              value={karatText}
              onChange={(e) => setKaratText(e.target.value)}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Gold weight (g)" />
            <TextField
              fullWidth
              size="small"
              type="number"
              value={weightG}
              onChange={(e) => setWeightG(e.target.value)}
            />
          </Grid>

         

          <Grid
            item
            xs={12}
          >
            <Box
              sx={{
                border: '1px dashed #B0BEC5',
                borderRadius: 2,
                p: 2,
                background: '#F7FAFC',
              }}
            >
              <Row
                label="Gold value"
                value={goldPriceForWeight}
              />
              
              <Divider sx={{ my: 1 }} />
              <Row
                label="Final amount"
                value={finalAmount}
                strong
              />
            </Box>
          </Grid>
        </Grid>
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          variant="outlined"
          onClick={handleClose}
          sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
        >
          {t('purchase:cancel')}
        </Button>
        <Button
          variant="contained"
          onClick={handleAdd}
          disabled={finalAmount === null}
          sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
        >
          {t('purchase:add')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(AddPurchase);
